import SwaggerParser from "@apidevtools/swagger-parser";
import Ajv from "ajv";
import addFormats from "ajv-formats";

const api = await SwaggerParser.dereference("./openapi.yaml");
const schema =
  api.paths["/v1/users/{userId}"].get.responses["200"].content["application/json"].schema;

const ajv = new Ajv({ allErrors: true, strict: false });
addFormats(ajv);
const validate = ajv.compile(schema);

const res = await fetch("https://staging.example.com/v1/users/usr_8f2k");
const body = await res.json();

if (res.status !== 200 || !validate(body)) {
  console.error(res.status, validate.errors);
  process.exitCode = 1;
}
